func ProcessWithRetry(items []interface{}, maxRetries int, transform func(interface{}) (interface{}, error)) ([]interface{}, error) {
    var results []interface{}

    for _, item := range items {
        var result interface{}
        var err error

        // Retry loop
        for retry := 0; retry < maxRetries; retry++ {
            result, err = transform(item)
            if err == nil {
                results = append(results, result)
                break
            }
            // Continue to next retry if error occurred
        }

        // Check if item failed all retries
        if err != nil {
            return nil, fmt.Errorf("failed after %d retries: %w", maxRetries, err)
        }
    }

    return results, nil
}
```

