    go func(id int) {
        if value, ok := c.Get("shared:data"); ok {
            fmt.Printf("Goroutine %d read: %v\n", id, value)
        }
    }(i)
}
// No locks needed in calling code — thread-safety is built-in
```

### Pattern 3: Cache Invalidation

```go
// Selective invalidation
