// Bulk invalidation
c.Purge() // Clear all entries
```

### Pattern 4: Lazy Loading Pattern

```go
func getUser(id string, c *cache.Cache) User {
    // Try cache first
    if val, ok := c.Get("user:" + id); ok {
        return val.(User)
    }

    // Cache miss — fetch from database
    user := fetchFromDB(id)
    c.Set("user:"+id, user)
    return user
}
```

