## Complete Working Example

```go
package main

import (
    "fmt"
    "sync"
    "time"
    "yourmodule/cache"
)

func main() {
    // Initialize cache with 30-second TTL
    c := cache.New(30 * time.Second)

    // Example 1: Basic operations
    c.Set("greeting", "Hello, World!")
    c.Set("counter", 42)
    c.Set("config", map[string]string{
        "env":  "production",
        "port": "8080",
    })

    if val, ok := c.Get("greeting"); ok {
        fmt.Println("Retrieved:", val)
    }

    // Example 2: Concurrent writes and reads
    var wg sync.WaitGroup

    // 5 goroutines writing
    for i := 0; i < 5; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            c.Set(fmt.Sprintf("key:%d", id), fmt.Sprintf("value:%d", id))
            fmt.Printf("Writer %d: stored key:%d\n", id, id)
        }(i)
    }

    // 5 goroutines reading
    for i := 0; i < 5; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            time.Sleep(10 * time.Millisecond) // Ensure writes complete
            if val, ok := c.Get(fmt.Sprintf("key:%d", id)); ok {
                fmt.Printf("Reader %d: retrieved %v\n", id, val)
            }
        }(i)
    }

    wg.Wait()

    // Example 3: Cleanup
    c.Delete("greeting")
    fmt.Println("Deleted 'greeting' key")

    c.Purge()
    fmt.Println("Cache cleared")
}
```

