	c.Set("config:db", "postgresql://localhost:5432")

	var wg sync.WaitGroup
	readCount := 0
	var mu sync.Mutex

	// 20 concurrent readers
	for i := 1; i <= 20; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()

