**Demonstrates:** Mixed concurrent reads and writes (thread-safe)

```go
package main

import (
	"fmt"
	"sync"
	"time"
	"yourmodule/cache"
)

func main() {
	c := cache.New(30 * time.Second)

	var wg sync.WaitGroup
	reportMu := sync.Mutex{}
	operations := map[string]int{
		"writes": 0,
		"reads":  0,
	}

	// 5 writer goroutines
	for w := 1; w <= 5; w++ {
		wg.Add(1)
		go func(writerID int) {
			defer wg.Done()
			for i := 0; i < 10; i++ {
				key := fmt.Sprintf("data:writer%d:item%d", writerID, i)
				value := fmt.Sprintf("value_from_writer_%d_%d", writerID, i)
				c.Set(key, value)

				reportMu.Lock()
				operations["writes"]++
				reportMu.Unlock()

				time.Sleep(5 * time.Millisecond)
			}
		}(w)
	}

	// Allow writes to populate cache
	time.Sleep(50 * time.Millisecond)

	// 10 reader goroutines
	for r := 1; r <= 10; r++ {
		wg.Add(1)
		go func(readerID int) {
			defer wg.Done()
			for i := 0; i < 5; i++ {
				key := fmt.Sprintf("data:writer%d:item%d", (i%5)+1, i)
				if val, ok := c.Get(key); ok {
					fmt.Printf("Reader %d retrieved: %v\n", readerID, val)
					reportMu.Lock()
					operations["reads"]++
					reportMu.Unlock()
				}
				time.Sleep(3 * time.Millisecond)
			}
		}(r)
	}

	wg.Wait()

	fmt.Printf("\nOperations Summary:\n")
	fmt.Printf("Total writes: %d\n", operations["writes"])
	fmt.Printf("Total reads:  %d\n", operations["reads"])
	fmt.Println("All operations completed safely without data races!")
}
```

