## Example 8: Safe Type Assertion with Error Handling

**Demonstrates:** Best practice for type safety

```go
package main

import (
	"fmt"
	"time"
	"yourmodule/cache"
)

type Order struct {
	OrderID int
	Total   float64
}

func SafeGet[T any](c *cache.Cache, key string) (T, error) {
	var zero T
	val, ok := c.Get(key)
	if !ok {
		return zero, fmt.Errorf("key not found: %s", key)
	}

	result, ok := val.(T)
	if !ok {
		return zero, fmt.Errorf("type assertion failed for key: %s", key)
	}

	return result, nil
}

func main() {
	c := cache.New(1 * time.Minute)

	// Store an Order
	order := Order{OrderID: 12345, Total: 199.99}
	c.Set("order:12345", order)

	// Safe retrieval with error handling
	if result, err := SafeGet[Order](c, "order:12345"); err != nil {
		fmt.Printf("Error: %v\n", err)
	} else {
		fmt.Printf("Order retrieved: ID=%d, Total=$%.2f\n", result.OrderID, result.Total)
	}

	// Attempt to retrieve with wrong type
	if _, err := SafeGet[string](c, "order:12345"); err != nil {
		fmt.Printf("Expected error: %v\n", err)
	}

	// Attempt to retrieve non-existent key
	if _, err := SafeGet[Order](c, "order:99999"); err != nil {
		fmt.Printf("Expected error: %v\n", err)
	}
}
```

**Output:**
```
Order retrieved: ID=12345, Total=$199.99
Expected error: type assertion failed for key: order:12345
Expected error: key not found: order:99999
```

