)

type UserRepository struct {
	cache *cache.Cache
}

type User struct {
	ID   int
	Name string
	Role string
}

// Simulates database query
func (ur *UserRepository) fetchFromDatabase(userID int) User {
	// Simulate expensive database operation
	time.Sleep(100 * time.Millisecond)
	return User{
		ID:   userID,
		Name: fmt.Sprintf("User_%d", userID),
		Role: "user",
	}
}

// GetUser retrieves from cache or database
func (ur *UserRepository) GetUser(userID int) User {
	cacheKey := fmt.Sprintf("user:%d", userID)

	// Try cache first
	if val, ok := ur.cache.Get(cacheKey); ok {
		fmt.Printf("[CACHE HIT] User %d\n", userID)
		return val.(User)
	}

	// Cache miss - fetch from database
	fmt.Printf("[CACHE MISS] Fetching user %d from database...\n", userID)
	user := ur.fetchFromDatabase(userID)

	// Store in cache
	ur.cache.Set(cacheKey, user)
	return user
}

func main() {
	c := cache.New(5 * time.Minute)
	repo := &UserRepository{cache: c}

	var wg sync.WaitGroup

	// First access - cache miss, database query
	for i := 1; i <= 3; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			user := repo.GetUser(id)
			fmt.Printf("Retrieved: %s (ID: %d, Role: %s)\n\n", user.Name, user.ID, user.Role)
		}(i)
	}
	wg.Wait()

	// Second access - cache hits
	fmt.Println("--- Second access (should be cache hits) ---\n")
	for i := 1; i <= 3; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			user := repo.GetUser(id)
			fmt.Printf("Retrieved: %s (ID: %d)\n\n", user.Name, user.ID)
		}(i)
	}
	wg.Wait()
}
```

