### Example 7: TTL-Based Expiration

```go
package main

import (
	"fmt"
	"time"
	"yourmodule/cache"
)

func main() {
	// Create cache with 2-second TTL
	c := cache.New(2 * time.Second)

	c.Set("temporary", "this will expire")
	fmt.Println("Stored value with 2-second TTL")

	// Retrieve immediately
	if val, ok := c.Get("temporary"); ok {
		fmt.Printf("At 0s: Retrieved '%v'\n", val)
	}

	// Wait 1 second
	time.Sleep(1 * time.Second)
	if val, ok := c.Get("temporary"); ok {
		fmt.Printf("At 1s: Retrieved '%v'\n", val)
	}

	// Wait another 1.5 seconds (total 2.5s > TTL)
	time.Sleep(1500 * time.Millisecond)
	if val, ok := c.Get("temporary"); !ok {
		fmt.Println("At 2.5s: Value has expired (as expected)")
	}
}
```

**Output:**
```
Stored value with 2-second TTL
At 0s: Retrieved 'this will expire'
At 1s: Retrieved 'this will expire'
At 2.5s: Value has expired (as expected)
```

