## Clean Interface Design

```typescript
// ============================================
// VALIDATION INTERFACE
// ============================================
interface ValidationResult {
  isValid: boolean;
  errors: Record<string, string>;
}

interface IValidator {
  validate(data: unknown): ValidationResult;
}

// ============================================
// NORMALIZATION INTERFACE
// ============================================
interface INormalizer {
  normalize(data: RawUserData): NormalizedUserData;
}

// ============================================
// PERSISTENCE INTERFACE
// ============================================
interface IUserRepository {
  findByEmail(email: string): Promise<User | null>;
  save(user: User): Promise<User>;
}

// ============================================
// NOTIFICATION INTERFACE
// ============================================
interface INotificationService {
  notifyUserCreated(user: User): Promise<void>;
  notifyAnalytics(event: AnalyticsEvent): Promise<void>;
}

// ============================================
// ORCHESTRATION INTERFACE (PUBLIC)
// ============================================
interface IUserRequestHandler {
  handleRequest(request: UserRequest): Promise<UserResponse>;
}

// ============================================
// IMPLEMENTATION: Clean Separation
// ============================================
class UserRequestHandler implements IUserRequestHandler {
  constructor(
    private validator: IValidator,
    private normalizer: INormalizer,
    private repository: IUserRepository,
    private notificationService: INotificationService
  ) {}

  async handleRequest(request: UserRequest): Promise<UserResponse> {
    // Step 1: VALIDATE
    const validation = this.validator.validate(request);
    if (!validation.isValid) {
      return this.buildErrorResponse(validation.errors);
    }

    // Step 2: NORMALIZE
    const normalized = this.normalizer.normalize(request);

    // Step 3: PERSIST
    const user = await this.repository.findByEmail(normalized.email);
    const savedUser = await this.repository.save(
      user ? { ...user, ...normalized } : normalized
    );

    // Step 4: NOTIFY
    await this.notificationService.notifyUserCreated(savedUser);
    await this.notificationService.notifyAnalytics({
      event: 'user_request_processed',
      userId: savedUser.id
    });

    // Step 5: RESPONSE ASSEMBLY (minimal logic)
    return this.buildSuccessResponse(savedUser);
  }

  private buildErrorResponse(errors: Record<string, string>): UserResponse {
    return { success: false, errors };
  }

  private buildSuccessResponse(user: User): UserResponse {
    return { success: true, data: user };
  }
}
