## Step 1: Validator Implementation

```typescript
class UserValidator implements IValidator {
  validate(data: unknown): ValidationResult {
    const errors: Record<string, string> = {};

    // Type guard
    if (typeof data !== 'object' || data === null) {
      return { isValid: false, errors: { root: 'Data must be an object' } };
    }

    const request = data as Record<string, unknown>;

    // Email validation
    if (!request.email || typeof request.email !== 'string') {
      errors.email = 'Email is required and must be a string';
    } else if (!this.isValidEmail(request.email)) {
      errors.email = 'Email format is invalid';
    }

    // Name validation
    if (!request.name || typeof request.name !== 'string') {
      errors.name = 'Name is required and must be a string';
    } else if (request.name.trim().length < 2) {
      errors.name = 'Name must be at least 2 characters';
    }

    // Age validation (optional)
    if (request.age !== undefined && request.age !== null) {
      if (typeof request.age !== 'number' || request.age < 0 || request.age > 150) {
        errors.age = 'Age must be a number between 0 and 150';
      }
    }

    return {
      isValid: Object.keys(errors).length === 0,
      errors
    };
  }

  private isValidEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }
}
```

## Step 2: Normalizer Implementation

```typescript
class UserNormalizer implements INormalizer {
  normalize(data: RawUserData): NormalizedUserData {
    return {
      email: this.normalizeEmail(data.email),
      name: this.normalizeName(data.name),
      age: this.normalizeAge(data.age),
      createdAt: new Date(),
      updatedAt: new Date()
    };
  }

  private normalizeEmail(email: string): string {
    return email.toLowerCase().trim();
  }

  private normalizeName(name: string): string {
    return name
      .trim()
      .split(/\s+/)
      .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
      .join(' ');
  }

  private normalizeAge(age?: number): number | undefined {
    return age !== undefined ? Math.floor(age) : undefined;
  }
}
