## Step 3: Repository Implementation

```typescript
class UserRepository implements IUserRepository {
  constructor(private database: Database) {}

  async findByEmail(email: string): Promise<User | null> {
    try {
      const user = await this.database.query(
        'SELECT * FROM users WHERE email = ?',
        [email]
      );
      return user || null;
    } catch (error) {
      throw new RepositoryError(`Failed to find user by email: ${error}`);
    }
  }

  async save(user: User): Promise<User> {
    try {
      if (user.id) {
        await this.database.query(
          'UPDATE users SET name = ?, age = ?, updated_at = ? WHERE id = ?',
          [user.name, user.age, user.updatedAt, user.id]
        );
        return user;
      } else {
        const result = await this.database.query(
          'INSERT INTO users (email, name, age, created_at, updated_at) VALUES (?, ?, ?, ?, ?)',
          [user.email, user.name, user.age, user.createdAt, user.updatedAt]
        );
        return { ...user, id: result.insertId };
      }
    } catch (error) {
      throw new RepositoryError(`Failed to save user: ${error}`);
    }
  }
}
