```go
// Validator - handles validation + normalization
func validateAndNormalize(req Request) (*Request, error) {
    if req.Name == "" { return nil, errors.New("name required") }
    if req.Age < 0 { return nil, errors.New("invalid age") }
    if req.Email == "" { return nil, errors.New("email required") }

    req.Name = strings.TrimSpace(req.Name)
    req.Email = strings.ToLower(req.Email)
    return &req, nil
}

// Processor - handles business logic
func createUser(req *Request) (*User, error) {
    return db.FindOrCreate(req.Name, req.Email, req.Age)
}

// Notifier - handles side effects
func notifyUser(user *User) error {
    mailer.Send(user.Email, "Welcome", "Hello "+user.Name)
    analytics.Track("user_created", user.ID)
    return nil
}

// Orchestrator - coordinates responsibilities
func handleRequest(req Request) Response {
    validated, err := validateAndNormalize(req)
    if err != nil { return Response{Error: err.Error()} }

    user, err := createUser(validated)
    if err != nil { return Response{Error: err.Error()} }

    notifyUser(user)
    return Response{UserID: user.ID}
}
