**FIXED CODE:**
```go
import (
    "path/filepath"
    "strings"
)

// Sanitize filename to prevent directory traversal
func sanitizeFilename(filename string) (string, error) {
    // Remove any path separators and traversal sequences
    filename = filepath.Base(filename)

    // Block empty filenames
    if filename == "" || filename == "." {
        return "", fmt.Errorf("invalid filename")
    }

    // Reject hidden files and suspicious patterns
    if strings.HasPrefix(filename, ".") || 
       strings.Contains(filename, "..") ||
       strings.ContainsAny(filename, "/\\") {
        return "", fmt.Errorf("filename contains illegal characters")
    }

    return filename, nil
}

// Usage in upload handler
cleanFilename, err := sanitizeFilename(header.Filename)
if err != nil {
    http.Error(w, "Invalid filename", http.StatusBadRequest)
    return
}
path := filepath.Join("/uploads", cleanFilename)
```

