### 2. **Insufficient Input Validation (CWE-434) - HIGH** ✓

**FIXED CODE:**
```go
const (
    maxFileSize = 10 * 1024 * 1024 // 10MB
    uploadDir   = "/uploads"
)

var allowedMimeTypes = map[string]bool{
    "application/pdf":                 true,
    "image/jpeg":                      true,
    "image/png":                       true,
    "application/vnd.ms-excel":        true,
}

var allowedExtensions = map[string]bool{
    ".pdf": true,
    ".jpg": true,
    ".png": true,
    ".xls": true,
}

func validateUpload(header *multipart.FileHeader, file multipart.File) error {
    // Check file size
    if header.Size > maxFileSize {
        return fmt.Errorf("file exceeds maximum size of %d bytes", maxFileSize)
    }

    // Validate extension
    ext := strings.ToLower(filepath.Ext(header.Filename))
    if !allowedExtensions[ext] {
        return fmt.Errorf("file type '%s' not allowed", ext)
    }

    // Validate MIME type (read first 512 bytes)
    buffer := make([]byte, 512)
    _, err := file.Read(buffer)
    if err != nil && err != io.EOF {
        return fmt.Errorf("failed to read file for validation")
    }

    mimeType := http.DetectContentType(buffer)
    if !allowedMimeTypes[mimeType] {
        return fmt.Errorf("MIME type '%s' not allowed", mimeType)
    }

    // Reset file pointer after reading
    file.Seek(0, 0)
    return nil
}
```

