func handleUpload(w http.ResponseWriter, r *http.Request) {
    file, header, err := r.FormFile("document")
    if err != nil {
        logger.Printf("ERROR: FormFile failed: %v", err)
        http.Error(w, "Invalid request", http.StatusBadRequest)
