    if err != nil {
        logger.Printf("SECURITY: Filename rejected - %v", err)
        http.Error(w, "Invalid filename", http.StatusBadRequest)
        return
    }

    // Validate upload (CWE-434 prevention)
    if err := validateUpload(header, file); err != nil {
        logger.Printf("SECURITY: Validation failed - %v", err)
        http.Error(w, "Upload validation failed", http.StatusBadRequest)
        return
    }

    path := filepath.Join(uploadDir, cleanFilename)
    out, err := os.Create(path) // CWE-390 prevention
    if err != nil {
        logger.Printf("ERROR: Create failed: %v", err)
        http.Error(w, "Storage error", http.StatusInternalServerError)
        return
    }
    defer out.Close()

    _, err = io.Copy(out, file)
    if err != nil {
        logger.Printf("ERROR: Copy failed: %v", err)
        os.Remove(path)
        http.Error(w, "Upload failed", http.StatusInternalServerError)
        return
    }

    logger.Printf("SUCCESS: Uploaded %s (%d bytes)", cleanFilename, header.Size)
    w.WriteHeader(http.StatusOK)
}
