// REMEDIATION FUNCTION: Input validation (CWE-20)
func sanitizeFilename(filename string) string {
	// Max length enforcement
	const maxLen = 255
	if len(filename) > maxLen {
		return ""
	}

	// Remove directory traversal sequences
	filename = filepath.Base(filename)

	// Whitelist allowed characters: alphanumeric, dash, underscore, dot
	var allowed strings.Builder
	for _, r := range filename {
		if (r >= 'a' && r <= 'z') ||
			(r >= 'A' && r <= 'Z') ||
			(r >= '0' && r <= '9') ||
			r == '-' || r == '_' || r == '.' {
			allowed.WriteRune(r)
		}
	}

	sanitized := allowed.String()
	if sanitized == "" || strings.HasPrefix(sanitized, ".") {
		return "" // Reject empty or hidden files
	}

	return sanitized
}

// REMEDIATION FUNCTION: Security logging (CWE-252)
func logSecurityEvent(eventType, details string) {
	// Log to secure audit trail
	fmt.Printf("[SECURITY] %s: %s\n", eventType, details)
	// In production: write to syslog or SIEM
}
