func handleFileUpload(w http.ResponseWriter, r *http.Request) error {
    file, header, err := r.FormFile("document")
    if err != nil {
        return fmt.Errorf("form file error: %w", err)
    }
    defer file.Close()

    // 1. Sanitize filename (CWE-22)
    sanitizedName := filepath.Base(header.Filename)
    if sanitizedName == "" || sanitizedName == "." || sanitizedName == ".." {
        return fmt.Errorf("invalid filename")
    }

    // 2. Validate input (CWE-20)
    if !allowedChars.MatchString(sanitizedName) {
        return fmt.Errorf("invalid characters in filename")
    }
    if !strings.HasSuffix(strings.ToLower(sanitizedName), ".pdf") {
        return fmt.Errorf("only PDF files allowed")
    }
    if header.Size > 10*1024*1024 {
        return fmt.Errorf("file too large")
    }

    // 3. Verify path stays within directory
    path := filepath.Join("/uploads", sanitizedName)
    absPath, _ := filepath.Abs(path)
    uploadsDir, _ := filepath.Abs("/uploads")
    if !strings.HasPrefix(absPath, uploadsDir) {
        return fmt.Errorf("path traversal blocked")
    }

    // 4. Create file with proper error handling (CWE-391)
    out, err := os.Create(path)
    if err != nil {
        return fmt.Errorf("create error: %w", err)
    }
    defer out.Close()

    if _, err := io.Copy(out, file); err != nil {
        return fmt.Errorf("write error: %w", err)
    }

