// isSorted verifies the output is sorted in ascending order
func isSorted(arr []int) bool {
	for i := 0; i < len(arr)-1; i++ {
		if arr[i] > arr[i+1] {
			return false
		}
	}
	return true
}

// hasSameElements verifies output contains exactly the same elements as input
func hasSameElements(result, input []int) bool {
	if len(result) != len(input) {
		return false
	}

	// Count occurrences in input
	inputCounts := make(map[int]int)
	for _, v := range input {
		inputCounts[v]++
	}

	// Count occurrences in result
	resultCounts := make(map[int]int)
	for _, v := range result {
		resultCounts[v]++
	}

	// Compare counts
	if len(inputCounts) != len(resultCounts) {
		return false
	}

	for k, v := range inputCounts {
		if resultCounts[k] != v {
			return false
		}
	}

	return true
}

