			// Property: output contains exactly the same elements as input
			// ============================================
			resultFreq := make(map[int]int)
			inputFreq := make(map[int]int)

			for _, v := range result {
				resultFreq[v]++
			}
			for _, v := range tt.input {
				inputFreq[v]++
			}

			if len(resultFreq) != len(inputFreq) {
				t.Errorf("PROPERTY 3 VIOLATED: different unique elements count")
			}

			for key, count := range inputFreq {
				if resultFreq[key] != count {
					t.Errorf("PROPERTY 3 VIOLATED: element %d appears %d times in input but %d times in result",
						key, count, resultFreq[key])
				}
			}

			// ============================================
			// PROPERTY 4: Sorted Order
			// Property: each element is <= the next element
			// ============================================
			for i := 0; i < len(result)-1; i++ {
				if result[i] > result[i+1] {
					t.Errorf("PROPERTY 4 VIOLATED: not sorted at index %d: %d > %d",
						i, result[i], result[i+1])
				}
			}

			// ============================================
			// PROPERTY 5: Stability Check (for duplicates)
			// Property: relative order of equal elements preserved
			// (if implementation maintains stability)
			// ============================================
			if len(result) > 0 && isSortedAndStable(result) {
				// This verifies output is both sorted and stable
				for i := 0; i < len(result)-1; i++ {
					if result[i] > result[i+1] {
						t.Errorf("PROPERTY 5 VIOLATED: stability check failed at index %d", i)
					}
				}
			}
		})
	}
}

// Helper function to verify sorted output
func isSortedAndStable(arr []int) bool {
	for i := 0; i < len(arr)-1; i++ {
		if arr[i] > arr[i+1] {
			return false
		}
	}
	return true
}

